 "places": [{"name": "Beijing, China", "role": "Cultural center"}, {"name": "London, England", "role": "Political influence"}, {"name": "Washington, D.C., USA", "role": "Government reform"}], "texts": [{"title": "Wikipedia: meritocracy", "type": "Reference article", "slug": "meritocracy"}], "externalLinks": ["https://www.wikidata.org/wiki/Q178079", "https://en.wikipedia.org/wiki/Meritocracy"], "tags": ["form of government", "Political Parties & Organizations", "cause-and-effect"], "thumbnailUrl": "", "quote": "", "legacySummary": "meritocracy left a notable mark on Classical history, documented across 73 Wikipedia editions worldwide. Key lasting impacts include: Shaped institutional landscape and community development. Their legacy is studied through the lens of historical causation.", "historicalSignificance": {"significanceScore": 7, "significanceNarrative": "Meritocracy transformed governance practices, leading to a more efficient administration and greater social mobility, influencing political systems worldwide. Its principles continue to underpin discussions of equality and opportunity in modern democracies.", "significanceCategory": "regional"}, "_editLog": [{"timestamp": "2026-06-07T17:01:34Z", "editorId": "gpt-4o-mini·cloud·GH#27098911410", "field": "summary", "oldValue": "Political system in which capital is assigned on the basis of competence", "newValue": "Meritocracy, a political system that assigns power and resources based on individual competence, emerged prominently in ancient China during the Han dynasty (206 BCE – 220 CE) but has roots in earlier philosophical traditions. This system, which can be traced to Confucian ideals advocating for governance by the virtuous and educated, reshaped societal structures and governance throughout history. The concept gained traction globally, particularly in Europe and the Americas during the Enlightenment, influencing modern democratic ideals and governance approaches, making it a vital aspect of political discourse.

